-- ============================================================
-- Machitori PROD sync: schema (migrations 0040-0044) + data
-- Generated for Supabase dashboard SQL editor. Idempotent; safe to re-run.
-- Runs as ONE transaction: any error rolls the whole thing back.
-- ============================================================
BEGIN;

-- ========== SCHEMA: 0040 customer_orders ==========
ALTER TABLE public.items ADD COLUMN IF NOT EXISTS sell_price NUMERIC(14,2);
CREATE TABLE IF NOT EXISTS public.customers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  phone TEXT NOT NULL UNIQUE, name TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE SEQUENCE IF NOT EXISTS public.order_seq;
CREATE TABLE IF NOT EXISTS public.orders (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  seq BIGINT NOT NULL DEFAULT nextval('public.order_seq'),
  order_number TEXT GENERATED ALWAYS AS (chr(65 + ((seq - 1) / 999)::int) || lpad((((seq - 1) % 999) + 1)::text, 3, '0')) STORED,
  customer_id UUID REFERENCES public.customers(id) ON DELETE SET NULL,
  customer_phone TEXT, customer_name TEXT,
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','preparing','ready','completed','cancelled')),
  total NUMERIC(14,2) NOT NULL DEFAULT 0, notes TEXT, printed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_status_idx ON public.orders (status);
CREATE INDEX IF NOT EXISTS orders_created_idx ON public.orders (created_at DESC);
DROP TRIGGER IF EXISTS orders_touch ON public.orders;
CREATE TRIGGER orders_touch BEFORE UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE IF NOT EXISTS public.order_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  item_id UUID REFERENCES public.items(id) ON DELETE SET NULL,
  name_snapshot TEXT NOT NULL, qty NUMERIC NOT NULL CHECK (qty > 0),
  unit_price NUMERIC(14,2) NOT NULL DEFAULT 0, line_total NUMERIC(14,2) NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS order_items_order_idx ON public.order_items (order_id);
ALTER TABLE public.customers   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders      ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Authenticated can read customers" ON public.customers;
CREATE POLICY "Authenticated can read customers" ON public.customers FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Authenticated can read orders" ON public.orders;
CREATE POLICY "Authenticated can read orders" ON public.orders FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Authenticated can update orders" ON public.orders;
CREATE POLICY "Authenticated can update orders" ON public.orders FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Authenticated can read order_items" ON public.order_items;
CREATE POLICY "Authenticated can read order_items" ON public.order_items FOR SELECT TO authenticated USING (true);
DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.orders;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.order_items;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ========== SCHEMA: 0041 tables ==========
CREATE TABLE IF NOT EXISTS public.tables (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL,
  code TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.tables ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Authenticated manage tables" ON public.tables;
CREATE POLICY "Authenticated manage tables" ON public.tables FOR ALL TO authenticated USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Public read tables" ON public.tables;
CREATE POLICY "Public read tables" ON public.tables FOR SELECT TO anon USING (true);
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS table_id UUID REFERENCES public.tables(id) ON DELETE SET NULL;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS table_name_snapshot TEXT;
ALTER TABLE public.orders ALTER COLUMN customer_phone DROP NOT NULL;
CREATE INDEX IF NOT EXISTS orders_table_idx ON public.orders (table_id);

-- ========== SCHEMA: 0042 loyalty ==========
CREATE TABLE IF NOT EXISTS public.loyalty_settings (
  id INTEGER PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  rp_per_point INTEGER NOT NULL DEFAULT 1000, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.loyalty_accounts (
  ig_handle TEXT PRIMARY KEY, total_points INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.loyalty_transactions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ig_handle TEXT NOT NULL REFERENCES public.loyalty_accounts(ig_handle) ON DELETE CASCADE,
  order_id UUID REFERENCES public.orders(id) ON DELETE SET NULL,
  points INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS points_earned INTEGER;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS points_claimed_at TIMESTAMPTZ;
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS loyalty_ig_handle TEXT;
ALTER TABLE public.loyalty_settings     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.loyalty_accounts     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.loyalty_transactions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Staff manage loyalty settings" ON public.loyalty_settings;
CREATE POLICY "Staff manage loyalty settings" ON public.loyalty_settings FOR ALL TO authenticated USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Staff read loyalty accounts" ON public.loyalty_accounts;
CREATE POLICY "Staff read loyalty accounts" ON public.loyalty_accounts FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "Staff read loyalty transactions" ON public.loyalty_transactions;
CREATE POLICY "Staff read loyalty transactions" ON public.loyalty_transactions FOR SELECT TO authenticated USING (true);

-- ========== SCHEMA: 0043 points_void ==========
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS points_void BOOLEAN NOT NULL DEFAULT FALSE;

-- ========== SCHEMA: 0044 item_addon ==========
ALTER TABLE public.items ADD COLUMN IF NOT EXISTS is_addon BOOLEAN NOT NULL DEFAULT FALSE;

